import React,{useEffect,useState} from "react";
import {ArrowUpRight, Boxes, PackageCheck, Users, Warehouse} from "lucide-react";
import {Link} from "react-router-dom";
import api from "../services/api";
import StatCard from "../components/StatCard";

export default function Dashboard() {
  const [members,setMembers]=useState([]);
  const [proc,setProc]=useState([]);
  const [sales,setSales]=useState([]);
  const [stock,setStock]=useState([]);

  useEffect(()=>{
    Promise.allSettled([
      api.get("/members"),
      api.get("/procurements"),
      api.get("/sales-orders"),
      api.get("/warehouse/stock")
    ]).then(r=>{
      setMembers(r[0].status==="fulfilled"?r[0].value.data:[]);
      setProc(r[1].status==="fulfilled"?r[1].value.data:[]);
      setSales(r[2].status==="fulfilled"?r[2].value.data:[]);
      setStock(r[3].status==="fulfilled"?r[3].value.data:[]);
    });
  },[]);

  const name=localStorage.getItem("name")||"User";

  return (
    <>
      <div className="page-head">
        <div>
          <span className="eyebrow">OVERVIEW</span>
          <h2>Good to see you, {name} 👋</h2>
          <p>Here's a quick view of your FPO operations.</p>
        </div>
      </div>

      <div className="stats-grid">
        <StatCard icon={Users} label="Members" value={members.length}/>
        <StatCard icon={PackageCheck} label="Procurements" value={proc.length}/>
        <StatCard icon={Boxes} label="Sales Orders" value={sales.length}/>
        <StatCard icon={Warehouse} label="Warehouses" value={stock.length}/>
      </div>

      <div className="two-col">
        <div className="panel">
          <div className="panel-head">
            <div><h3>Recent procurement</h3><p>Latest farmer transactions</p></div>
            <Link to="/procurement">View all <ArrowUpRight size={15}/></Link>
          </div>

          {proc.length ? (
            <div className="table-wrap">
              <table>
                <thead><tr><th>Member</th><th>Commodity</th><th>Qty</th><th>Total</th><th>Status</th></tr></thead>
                <tbody>
                  {proc.slice(0,6).map(p=>(
                    <tr key={p.id}>
                      <td>{p.member?.name||"-"}</td><td>{p.commodity}</td>
                      <td>{p.quantityKg} kg</td><td>₹{p.totalAmount}</td>
                      <td><span className="badge pending">{p.paymentStatus}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : <div className="empty">No procurement records found.</div>}
        </div>

        <div className="panel insight">
          <span className="insight-icon">🌱</span>
          <h3>FPO at a glance</h3>
          <p>Keep farmer records, procurement, sales and warehouse operations connected in one place.</p>
          <Link className="text-link" to="/analytics">Open analytics →</Link>
        </div>
      </div>
    </>
  );
}
